n = int(input())

gates = []

for _ in range(n):
    gates.append(input().split())

a, b = map(int, input().split())

values = {
    "A": a,
    "B": b
}

for gate in gates:
    gid = gate[0]
    op = gate[1]

    if op == "BUFFER":
        values[gid] = values[gate[2]]

    elif op == "NOT":
        values[gid] = 1 - values[gate[2]]

    else:
        x = values[gate[2]]
        y = values[gate[3]]

        if op == "AND":
            values[gid] = x & y

        elif op == "OR":
            values[gid] = x | y

        elif op == "NAND":
            values[gid] = 1 - (x & y)

        elif op == "NOR":
            values[gid] = 1 - (x | y)

        elif op == "XOR":
            values[gid] = x ^ y

        elif op == "XNOR":
            values[gid] = 1 - (x ^ y)

print(values[gates[-1][0]])
